get_settings.code:
use WebCommander\Resources\CommonSettings\CommonSettings;

$response = CommonSettings::getSettings($client, ['type' => 'customer_registration_field', 'config_key' => 'abn_placeholder']);

foreach ($response->map['settings']['customer_registration_field'] as $entry) {
    echo $entry['config_key'], ': ', $entry['value'], PHP_EOL;
}

update_settings.code:
use WebCommander\Resources\CommonSettings\CommonSettings;

$response = CommonSettings::updateSettings($client, ['settings' => [
    'customer_registration_field' => [['config_key' => 'abn_placeholder', 'value' => 'Enter your ABN']],
]]);

foreach ($response->map['settings']['customer_registration_field'] as $entry) {
    if ($entry['config_key'] === 'abn_placeholder') {
        echo $entry['config_key'], ': ', $entry['value'], PHP_EOL;
    }
}

